/* 词序42 — local-first vocabulary sprint. No accounts or tracking. */
(function () {
  'use strict';
  const E = window.Engine;
  const words = window.WORDS || [];
  const byId = new Map(words.map(w => [String(w.id), w]));
  const core = words.filter(w => w.core);
  const articles = window.LEARNING_ARTICLES || [];
  const essays = window.ESSAYS || [];
  const KEY = 'word42.progress.v1', PREF = 'word42.preferences.v1';
  const $ = s => document.querySelector(s);
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const today = () => E.dateKey(new Date());
  if (!E || !words.length) { $('#main').innerHTML = '<div class="empty">词库未加载。请重新打开页面或检查应用文件是否完整。</div>'; return; }
  let state, prefs = { readDays: [], readingNotes: {}, showTranslation: true };
  let storageOK = true, view = 'home', libraryTab = 'core', search = '', showBasic = false, page = 1, session = null;
  let toastTimer, installPrompt = null;
  try { const raw = localStorage.getItem(KEY); state = raw ? E.validateImport(JSON.parse(raw), words) : E.createState(today()); }
  catch (error) { state = E.createState(today()); storageOK = false; }
  try { const raw = JSON.parse(localStorage.getItem(PREF) || '{}'); if (raw && typeof raw === 'object') { prefs.readDays = Array.isArray(raw.readDays) ? raw.readDays.filter(n => Number.isInteger(n) && n >= 1 && n <= 42) : []; prefs.readingNotes = raw.readingNotes && typeof raw.readingNotes === 'object' ? raw.readingNotes : {}; prefs.showTranslation = raw.showTranslation !== false; } } catch (_) { storageOK = false; }
  if (!E || !words.length) { $('#main').innerHTML = '<div class="empty">词库未加载。请重新打开页面或检查应用文件是否完整。</div>'; return; }
  const icons = {
    home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    library: '<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3zM12 6v16"/>',
    progress: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-14 4h3m4 0h3"/>',
    methods: '<path d="M9 18h6m-5 3h4M8 15c0-2-3-3-3-7a7 7 0 0 1 14 0c0 4-3 5-3 7v1H8z"/>',
    writing: '<path d="m15 3 6 6-11 11-7 1 1-7zM13 5l6 6M3 21l5-5"/>',
    arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>',
    sound: '<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
    repeat: '<path d="M20 7H8a5 5 0 0 0-5 5m17-9v4l-4 4M4 17h12a5 5 0 0 0 5-5M4 21v-4l4-4"/>',
    check: '<path d="m4 12 5 5L20 6"/>',
    settings: '<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>'
  };
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.home}</svg>`;
  const navs = [['home','今日学习'],['library','我的词库'],['progress','42 天计划'],['methods','学习方法'],['writing','每日写作']];
  function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 3200); }
  function persist(next = state) { state = next; try { localStorage.setItem(KEY, JSON.stringify(state)); storageOK = true; } catch (_) { storageOK = false; toast('本机保存失败，请到设置导出备份，避免丢失进度。'); } updateSave(); }
  function savePrefs() { try { localStorage.setItem(PREF, JSON.stringify(prefs)); } catch (_) { toast('阅读记录保存失败，请检查浏览器存储空间。'); } }
  function updateSave() { $('#save-status').textContent = storageOK ? '进度存于本机' : '请导出进度备份'; }
  function stats() { return E.getStats(state, words, today()); }
  function go(name) { view = navs.some(n => n[0] === name) || name === 'settings' ? name : 'home'; location.hash = view; render(); window.scrollTo({top:0,behavior:'instant'}); }
  function navHTML(mobile) { return navs.map(([id,label]) => `<button data-nav="${id}" class="${mobile ? '' : 'nav-item '}${id === view ? 'active' : ''}" ${id === view ? 'aria-current="page"' : ''}>${icon(id)}<span>${mobile ? ({home:'今日',library:'词库',progress:'计划',methods:'方法',writing:'写作'}[id]) : label}</span></button>`).join(''); }
  function heading(title, sub, label = 'MAKE EVERY DAY COUNT') { return `<div class="heading-row"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${sub}</p></div><div class="date-badge">${icon('progress')}${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'})}</div></div>`; }
  function render() { $('#navigation').innerHTML = navHTML(false); $('#mobile-nav').innerHTML = navHTML(true); $('#page-name').textContent = navs.find(n => n[0] === view)?.[1] || '计划与设置'; const renderers = {home:renderHome,library:renderLibrary,progress:renderProgress,methods:renderMethods,writing:renderWriting,settings:renderSettings}; $('#main').innerHTML = renderers[view](); updateSave(); }
  function renderHome() {
    const s = stats(), current = Math.max(1, s.day), pct = Math.min(100, Math.round((s.learned || 0) / Math.max(1,s.total) * 100));
    const nextWords = E.getQueue(state, words, today(), 'new').filter(x=>x.kind==='new').slice(0,3).map(x => byId.get(String(x.id))).filter(Boolean);
    const essay = essays.find(x => x.day === Math.min(current,42)) || essays[0];
    return `${heading('今天，也向前一步。', '把陌生的单词，变成下一次考试里的底气。', 'HELLO, WORD EXPLORER')}
    ${s.backlogWarning?'<div class="notice">到期复习已超过60词。今天先分组清理复习，量力完成新词；未完成任务会保留，不必为了打卡赶进度。</div>':''}${!storageOK ? '<div class="notice">浏览器存储不可用或上次进度无法读取。请在设置中备份或恢复数据。</div>' : ''}
    <section class="hero"><div class="hero-main"><span class="hero-tag">✳ 42-DAY VOCABULARY SPRINT</span><h2>第 ${current} 天，<br><span>${s.newRemaining ? '让记忆再深一点。' : '把学过的，记得更牢。'}</span></h2><p>${current <= 35 ? `今天最多 ${s.dailyLimit || s.newGoal} 个新词，先复习，再学新。` : '巩固、检索、再回忆，走好冲刺最后一程。'}</p><div class="hero-actions"><button class="btn btn-primary" data-start="all">${s.newRemaining || s.dueRemaining ? '开始今日学习' : '今日任务已完成'} <span>↗</span></button><button class="btn btn-quiet" data-nav="progress">查看我的计划 →</button></div></div><div class="hero-ring"><svg viewBox="0 0 160 160"><circle cx="80" cy="80" r="68" fill="none" stroke="#d9dfcb" stroke-width="5"/><circle cx="80" cy="80" r="68" fill="none" stroke="#839670" stroke-width="5" stroke-linecap="round" stroke-dasharray="${pct*4.2726} 427.26"/></svg><div class="ring-text"><b>${pct}<small>%</small></b><span>冲刺词已学习</span></div></div></section>
    <div class="dashboard-grid"><div><div class="section-heading"><h2>今日任务 <small>TODAY'S FOCUS</small></h2><span class="text-link">按自己的节奏来</span></div><div class="task-cards">
    <button class="task-card" data-start="new"><span class="task-icon">${icon('library')}</span><span class="mini-arrow">↗</span><label>新词学习</label><strong>${s.newRemaining}<small>词</small></strong><p>今日已完成 ${s.newDone} / ${s.newGoal}</p></button>
    <button class="task-card" data-start="review"><span class="task-icon">${icon('repeat')}</span><span class="mini-arrow">↗</span><label>到期复习</label><strong>${s.dueRemaining}<small>词</small></strong><p>${s.dueRemaining ? '现在回忆，正是时候' : '已学词会自动安排复习'}</p></button>
    <button class="task-card" data-quiz="spelling"><span class="task-icon">${icon('writing')}</span><span class="mini-arrow">↗</span><label>拼写自测</label><strong>10<small>题</small></strong><p>用主动检索加深记忆</p></button></div>
    <section class="panel week-panel"><div class="section-heading"><h2>保持自己的节奏</h2><span class="pill">连续 ${s.streak} 天</span></div><div class="days-row">${renderWeek()}</div><div class="week-bottom"><span>已打卡 <b>${s.checkInDays}</b> 天，每一天都算数。</span><button class="check-in" data-action="checkin">${s.checkedIn ? '✓ 今日已打卡' : '完成后打卡'}</button></div></section></div>
    <section class="panel memory-panel"><div class="section-heading"><h2>记忆，需要恰好的重逢</h2><span class="pill">间隔复习</span></div><p>在逐渐遗忘时主动回忆，<br>让单词慢慢成为长期记忆。</p><svg class="memory-chart" viewBox="0 0 260 100" aria-label="间隔复习示意图，非个人记忆率预测"><path d="M0 89H260M0 50H260M0 12H260" stroke="#edf0e6" stroke-dasharray="3 4" fill="none"/><path d="M5 15 Q17 70 75 82 T255 91" fill="none" stroke="#c8cfbb" stroke-dasharray="4 4" stroke-width="1.5"/><path d="M5 15Q17 39 41 48L43 15Q62 38 93 44L95 13Q126 32 156 36L158 11Q201 25 255 29" fill="none" stroke="#8ea97a" stroke-width="2"/><circle cx="43" cy="15" r="3" fill="#8ea97a"/><circle cx="95" cy="13" r="3" fill="#8ea97a"/><circle cx="158" cy="11" r="3" fill="#8ea97a"/></svg><div class="chart-labels"><span>首次学习</span><span>逐步拉长复习间隔 →</span></div><div class="chart-legend"><span><i class="legend-dot"></i>间隔检索</span><span><i class="legend-dot grey"></i>不复习 · 原理示意</span></div><div class="memory-callout"><strong>先试着想起来，再翻开答案。</strong><br>一次认真回忆，胜过机械地多看几遍。<button class="text-link" data-nav="methods"> 学习方法 →</button></div></section></div>
    <div class="daily-routine"><span>① 先复习：分组回忆</span><span>② 再学新：读音 + 词义</span><span>③ 少量输出：仿写一个句子</span></div><div class="bottom-grid"><section class="panel"><div class="section-heading"><h2>即将遇见的单词</h2><button class="text-link" data-nav="library">打开词库 ↗</button></div>${nextWords.length ? nextWords.map(w => `<div class="word-strip"><div><b>${esc(w.word)}</b><small>${esc(w.phonetic ? '/'+w.phonetic+'/' : 'CET-4 · 冲刺重点')}</small></div><p>${esc(w.meaning.split('\n')[0])}</p></div>`).join('') : '<div class="empty">今天的新词已完成。<br>给记忆一点沉淀的时间。</div>'}</section><section class="editorial-card"><div class="eyebrow">DAILY WRITING · DAY ${essay?.day || current}</div><h3>${esc(essay?.title || 'A little progress, every day.')}</h3><p>${esc(essay?.topic || '42 天四级写作练习')} · 结构拆解与表达迁移</p><button data-essay="${essay?.day || 1}">阅读今日范文 <span>↗</span></button></section></div><div class="method-chips"><button class="text-link" data-action="foundation-check">基础词补漏自测 →</button><span>600 词主学 + 100 词选学</span><span>先回忆，再翻卡</span><span>进度本机保存</span><button class="text-link" data-nav="settings">备份与设置 →</button></div>`;
  }
  function renderWeek() { const now = new Date(), weekDay = (now.getDay()+6)%7; return ['一','二','三','四','五','六','日'].map((name,i) => {const date=E.addDays(today(),i-weekDay), done=state.daily[date]?.checkedIn;return `<div class="day-cell ${date===today()?'today':''} ${done?'done':''}"><span>周${name}</span><strong>${done?'✓':Number(date.slice(-2))}</strong></div>`;}).join(''); }
  function filteredWords() { return words.filter(w => (showBasic || !w.base) && (libraryTab==='all' || libraryTab==='core'&&w.core || libraryTab==='cet4'&&w.tags.includes('cet4') || libraryTab==='gk'&&w.tags.includes('gk') || libraryTab==='favorites'&&state.favoriteIds.includes(w.id) || libraryTab==='learned'&&state.records[w.id]?.learned) && (!search || w.word.toLowerCase().includes(search.toLowerCase()) || w.meaning.includes(search))).sort((a,b)=>a.rank-b.rank || a.word.localeCompare(b.word)); }
  function renderLibrary() { const list=filteredWords(), size=40,pages=Math.max(1,Math.ceil(list.length/size));page=Math.min(page,pages);return `${heading('把每一个词，学得扎实。',`已收录 ${words.length.toLocaleString()} 个词条 · 基础词默认隐藏 · 600 词主学 + 100 词选学`, 'YOUR WORD COLLECTION')}<div class="notice">基础词默认隐藏以保持列表简洁；基础薄弱时，建议先做补漏自测。<button class="text-button" data-action="foundation-check">开始基础词自测 →</button></div><div class="toolbar"><input id="word-search" class="search-box" type="search" placeholder="搜索单词或中文释义…" aria-label="搜索单词或中文释义" value="${esc(search)}"><label class="toggle-label"><input type="checkbox" id="show-basic" ${showBasic?'checked':''}>显示基础词</label></div><div class="filter-tabs">${[['core','重点 700'],['cet4','四级词库'],['gk','高中词库'],['all','全部词条'],['favorites','我的收藏'],['learned','已经学过']].map(([id,label])=>`<button data-filter="${id}" class="${libraryTab===id?'active':''}">${label}</button>`).join('')}</div><div class="word-table">${list.length?list.slice((page-1)*size,page*size).map(w=>`<div class="library-row"><div><button class="library-word" data-word="${esc(w.id)}">${esc(w.word)}</button><div class="library-phonetic">${esc(w.phonetic?'/'+w.phonetic+'/':'音标暂缺')} ${w.core?'· 冲刺':w.base?'· 基础':'· 扩展'}</div></div><div class="library-meaning">${esc(w.meaning)}</div><div class="row-actions"><button class="icon-button" aria-label="朗读 ${esc(w.word)}" data-speak="${esc(w.id)}">♪</button><button class="icon-button ${state.favoriteIds.includes(w.id)?'selected':''}" data-favorite="${esc(w.id)}" aria-label="${state.favoriteIds.includes(w.id)?'取消收藏':'收藏'} ${esc(w.word)}">${state.favoriteIds.includes(w.id)?'★':'☆'}</button><button class="icon-button ${state.knownIds.includes(w.id)?'selected':''}" data-known="${esc(w.id)}" aria-label="${state.knownIds.includes(w.id)?'重新学习':'标记已会并跳过'} ${esc(w.word)}">✓</button></div></div>`).join(''):'<div class="empty">这里还没有单词。<br>试试其他筛选条件，或收藏想强化的词。</div>'}</div><div class="pagination"><span>共 ${list.length} 词 · 第 ${page} / ${pages} 页</span><div><button class="btn btn-light" data-page="${page-1}" ${page<=1?'disabled':''}>上一页</button> <button class="btn btn-light" data-page="${page+1}" ${page>=pages?'disabled':''}>下一页</button></div></div><p class="subtle" style="margin-top:18px">700 词按公开通用语料频率筛选；不代表四级真题频次排名。点击单词可将扩展词加入学习计划。</p>`; }
  function renderProgress() { const s=stats();return `${heading('42 天，让改变看得见。','前 35 天循序渐进学 600 词，最后 7 天集中巩固；另 100 词选学。','YOUR 42-DAY JOURNEY')}<div class="stat-grid"><div class="stat"><label>冲刺进度</label><strong>${Math.min(s.day,42)}<small> / 42 天</small></strong><small>开始于 ${state.startDate}</small></div><div class="stat"><label>学过的词</label><strong>${s.learned}<small> / ${s.total}</small></strong><small>完成第一次主动回忆</small></div><div class="stat"><label>进入长间隔</label><strong>${s.mastered || 0}<small> 词</small></strong><small>仍需要继续复习</small></div><div class="stat"><label>累计打卡</label><strong>${s.checkInDays}<small> 天</small></strong><small>连续打卡 ${s.streak} 天</small></div></div><section class="panel"><div class="section-heading"><h2>我的冲刺日历</h2><span class="pill">${s.day<=35?'积累期':'巩固期'}</span></div><div class="calendar-grid">${Array.from({length:42},(_,i)=>{const date=E.addDays(state.startDate,i),done=state.daily[date]?.checkedIn;return `<div class="calendar-cell ${done?'done':''} ${date===today()?'today':''}" title="${date}"><b>${String(i+1).padStart(2,'0')}</b><small>${done?'✓ 已打卡':i<35?`${i<5?10:i<15?15:20}词 + 复习`:'巩固复习'}</small></div>`;}).join('')}</div><p class="calendar-note">复习间隔依表现按 1、2、4、7、15 天逐步拉长，后续继续长期维护。忘记后会缩短间隔、加入重试。图表只反映学习记录，不预测个人记忆率。第 42 天后到期词仍然保留。</p></section><section class="panel" style="margin-top:22px"><div class="section-heading"><h2>今日完成条件</h2><button class="btn btn-primary" data-action="checkin">${s.checkedIn?'✓ 已打卡':'记录今天的坚持'}</button></div><p class="subtle">新词 ${s.newDone} / ${s.newGoal} · 到期及重试剩余 ${s.dueRemaining} 词。完成今日新词与待复习词后即可打卡。拼写自测与写作作为加练，不占用词汇打卡条件。</p></section>`; }
  function renderMethods() {return `${heading('用对方法，让记忆更深。','把间隔复习、主动检索和表达迁移，变成每天做得到的小动作。','LEARN HOW TO LEARN')}<div class="notice">这里采用间隔重复与主动检索的研究原则。复习天数是可执行的学习安排，并非对每个人都精确适用的“艾宾浩斯公式”。</div><div class="articles-grid">${articles.map((a,i)=>`<button class="article-card" data-article="${esc(a.id)}"><span class="eyebrow">FIELD NOTE ${String(i+1).padStart(2,'0')} · ${a.minutes || 3} MIN READ</span><h2>${esc(a.title)}</h2><p>${esc(a.subtitle)}</p><small>阅读方法 · 今天就试一试 ↗</small></button>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="section-heading"><h2>把方法用起来</h2></div><div class="settings-actions"><button class="btn btn-primary" data-start="all">先回忆，再翻卡</button><button class="btn btn-light" data-quiz="spelling">拼写检索 10 题</button><button class="btn btn-light" data-quiz="choice">词义自测 10 题</button></div><p class="subtle" style="margin-top:15px">优先从已学词出题；尚未学词时使用冲刺词预习。自测独立计分，答错的已学词会重新进入今日复习。</p></section>`; }
  function renderWriting() { const day=Math.min(Math.max(1,stats().day),42);return `${heading('每天一篇，把表达积累下来。',`42 篇原创四级训练范文 · 中英对照 · 结构拆解 · 已练习 ${prefs.readDays.length} 篇`,'DAILY WRITING STUDIO')}<div class="notice">以公开四级写作要求和常见主题为依据创作的训练范文，非真题原文、押题或官方标准答案。前期按任务练句子与段落，后期再限时独立写作；“读懂”不等于“会写”。</div><div class="essay-grid">${essays.map(e=>`<button class="essay-card ${e.day===day?'active':''}" data-essay="${e.day}"><span class="day-label">DAY ${String(e.day).padStart(2,'0')} <span>${prefs.readDays.includes(e.day)?'✓ 已练习':e.day===day?'今日推荐':''}</span></span><h2>${esc(e.title)}</h2><p>${esc(e.topic)} · ${esc(e.type)}</p><small>${e.wordCount || countWords(e.essay.join(' '))} words · 阅读、仿写、迁移 ↗</small></button>`).join('')}</div>`; }
  function renderSettings() { const meta=window.WORD_META||{};return `${heading('为自己，安排一个好节奏。','词库离线可读，进度保存在当前设备。换手机前，请先导出备份。','PLAN & PREFERENCES')}<div class="settings-grid"><section class="panel settings-panel"><h2>你的冲刺计划</h2><p>以基础薄弱为起点：第1–5天每天10词，第6–15天15词，第16–35天20词，共600词；第36–42天集中复习。另100词选学。漏学后可继续补学，额外加入的词可能延长计划。</p><label for="start-date">计划开始日期（修改不会删除已学记录）</label><input type="date" id="start-date" max="${today()}" value="${state.startDate}"> <button class="btn btn-light" data-action="save-date">保存</button><p class="settings-small" style="margin-top:16px">复习与打卡使用设备本地日期。手机换时区会影响“今天”的划分。请保持设备日期正确。</p><button class="btn btn-light" data-action="install">安装 / 添加到手机桌面 ↗</button></section><section class="panel settings-panel"><h2>备份与恢复</h2><p>浏览器清理数据、换设备或换网址后，进度不会自动同步。建议每周备份一次。</p><div class="settings-actions"><button class="btn btn-primary" data-action="export">导出备份文件</button><button class="btn btn-light" data-action="backup-text">显示备份文本</button><label class="btn btn-light" style="margin:0;cursor:pointer">导入文件<input type="file" id="import-file" accept="application/json,.json" hidden></label></div><label for="backup-text">也可以粘贴备份文本恢复（会覆盖当前记录）</label><textarea id="backup-text" placeholder="粘贴导出的 JSON 备份内容…" spellcheck="false"></textarea><button class="btn btn-light" data-action="import-text">校验并恢复</button></section><section class="panel settings-panel"><h2>关于词库与筛选</h2><p>词库共 ${words.length.toLocaleString()} 条，冲刺重点 ${core.length} 条。保留来源中全部四级和高中标签词；通过基础标签及人工基础词规则默认隐藏简单词。</p><p>700 词优先参考通用语料频率及考试词库交集；它是冲刺选词方案，不是已核验的四级真题高频榜，也不能替代历年真题练习。</p><p class="settings-small">开源词库的四级标签数量可能与某版官方大纲不同，软件不宣称覆盖所有现行考试词汇。可在词库页查看来源全集，并把需要的扩展词加入计划。</p><a class="source-link" href="https://github.com/skywind3000/ECDICT" target="_blank" rel="noopener noreferrer">查看 GitHub 开源词库 ECDICT ↗</a>${meta.additionalSource?`<p>${esc(meta.additionalSource)}</p>`:''}</section><section class="panel settings-panel"><h2>Mate 80 · HarmonyOS 7.0</h2><p>手机浏览器打开应用网址即可使用。若浏览器菜单提供“添加到桌面”，可创建快捷入口；具体安装行为以设备浏览器为准。</p><p>原生鸿蒙版使用 ArkWeb 本地页面，配套工程需要 DevEco Studio 编译、签名后安装。网页可用不代表已经获得可安装的 HAP。</p><p class="settings-small">朗读使用设备浏览器语音能力；缺少英语声音时会提示。网页不提供关闭后的系统提醒。应用不使用后台跟踪。</p><button class="text-button" data-action="reset">清空本机学习进度并重新开始</button></section></div>`; }
  function shortMeaning(text) { return String(text).split('\n').slice(0,2).map(line=>line.split(/[,，;；]/).slice(0,3).join('，')).join('\n'); }
  function countWords(text) { return (text.match(/[A-Za-z]+(?:['’\-][A-Za-z]+)*/g)||[]).length; }
  function openDetail(html) { $('#detail-content').innerHTML=`<div class="detail-content">${html}</div>`; if(!$('#detail-dialog').open)$('#detail-dialog').showModal(); $('#detail-dialog').scrollTop=0; }
  function sourcesHTML(sources) { return (sources||[]).length?`<h2>参考来源</h2><ul class="source-list">${sources.filter(s=>/^https:\/\//.test(s.url)).map(s=>`<li><a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></li>`).join('')}</ul>`:''; }
  function showArticle(id) { const a=articles.find(x=>String(x.id)===id);if(!a)return;openDetail(`<span class="eyebrow">LEARNING FIELD NOTES · ${a.minutes||3} MIN</span><h1>${esc(a.title)}</h1><p>${esc(a.subtitle)}</p>${a.body.map(p=>`<p>${esc(p)}</p>`).join('')}<h2>今天就这样做</h2><ol>${a.steps.map(p=>`<li>${esc(p)}</li>`).join('')}</ol>${sourcesHTML(a.sources)}<p class="subtle">研究支持学习原则；实际效果因材料、投入与复习安排而异。</p>`); }
  function showEssay(day) {const e=essays.find(x=>x.day===day);if(!e)return;openDetail(`<span class="eyebrow">DAY ${String(day).padStart(2,'0')} · ${e.wordCount||countWords(e.essay.join(' '))} WORDS · 原创训练范文</span><h1 style="font-family:Georgia,serif">${esc(e.title)}</h1><span class="pill">${esc(e.topic)} · ${esc(e.type)}</span><h2>${e.day<=5?'先读懂句子，不急着整篇写':e.day<=15?'先仿写一句，再看范文':e.day<=28?'先练段落，再连成篇':'先写，再对照范文'}</h2><div class="callout">${esc(e.prompt)}</div><label class="read-toggle"><input type="checkbox" id="translation-toggle" ${prefs.showTranslation?'checked':''}> 显示逐段中文对照</label>${e.essay.map((p,i)=>`<p class="english">${esc(p)}</p><p class="chinese" ${prefs.showTranslation?'':'hidden'}>${esc(e.translation[i]||'')}</p>`).join('')}<h2>文章是怎么展开的</h2><ol>${e.outline.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h2>把好表达带走</h2>${e.phrases.map(p=>`<div class="phrase"><b>${esc(p.en)}</b><span>${esc(p.zh)}</span></div>`).join('')}<h2>今日迁移练习</h2><div class="callout">${esc(e.task)}</div><label class="read-toggle" for="essay-notes">留下你的仿写或修改笔记</label><textarea maxlength="20000" id="essay-notes" data-day="${day}" placeholder="试着用自己的经历，重写其中一个例子…">${esc(prefs.readingNotes[day]||'')}</textarea><button class="btn btn-primary" data-read="${day}" style="margin-top:16px">${prefs.readDays.includes(day)?'✓ 已练习 · 保存笔记':'保存笔记并标记已练习'}</button>${sourcesHTML(e.sources)}`); }
  function showWord(id) {const w=byId.get(id);if(!w)return; const r=state.records[w.id];openDetail(`<span class="eyebrow">${w.core?'CORE 700':'EXTENDED VOCABULARY'}</span><h1 style="font:42px Georgia,serif">${esc(w.word)}</h1><p>${esc(w.phonetic?'/'+w.phonetic+'/':'')}</p><p style="white-space:pre-line">${esc(w.meaning)}</p><div class="settings-actions"><button class="btn btn-light" data-speak="${esc(w.id)}">♪ 朗读</button><button class="btn btn-light" data-favorite="${esc(w.id)}">${state.favoriteIds.includes(w.id)?'★ 已收藏':'☆ 收藏'}</button>${(!w.core || core.indexOf(w)>=600)?`<button class="btn btn-primary" data-extra="${esc(w.id)}">${state.knownIds.includes(w.id)?'恢复学习计划':state.extraIds.includes(w.id)?'已加入计划':'加入学习计划'}</button>`:''}</div><p class="subtle">${r?`下次复习：${esc(r.due)} · 累计尝试 ${r.attempts} 次`:'尚未开始学习'}</p><h2>加深记忆的小动作</h2><p>先合上释义，用自己的话说出意思；再用这个词写一句与你生活有关的句子。次日回忆时先试一次，再看答案。</p>`); }
  function speak(id) {const w=byId.get(id);if(!w)return;if(!('speechSynthesis' in window)){toast('当前设备不支持网页朗读，请参考音标。');return;}const voices=speechSynthesis.getVoices(),voice=voices.find(v=>/^en[-_]/i.test(v.lang));if(voices.length&&!voice){toast('设备未安装英语语音，请在系统中添加。');return;}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(w.word);utter.lang='en-US';utter.rate=.85;if(voice)utter.voice=voice;utter.onerror=()=>toast('朗读暂不可用，请检查系统英语语音。');speechSynthesis.speak(utter);}
  function openStudy(mode) {const queue=E.getQueue(state,words,today(),mode).slice(0,25);if(!queue.length){toast(mode==='review'?'没有到期复习词。先学习新词，明天再来回忆。':'这部分任务已完成，可以打卡或做一次自测。');return;}session={type:'cards',mode,queue:queue.map(x=>({id:String(x.id),kind:x.kind})),total:queue.length,completed:0,revealed:false,retries:[],date:today()};$('#study-dialog').showModal();renderStudy();}
  function renderStudy() {if(!session)return; const item=session.queue[0];if(!item){renderFinish();return;}const w=byId.get(item.id);if(!w){session.queue.shift();renderStudy();return;}if(session.type!=='cards'){renderQuiz(w);return;}const labels={new:'初次见面 · 读音与词义',review:'到期重逢 · 主动检索',retry:'再试一次 · 加深记忆'};$('#study-content').innerHTML=`<div class="study-top"><span>${session.mode==='review'?'到期复习':'今日学习'} · 已完成 ${session.completed} / ${session.total}</span><button class="close-button" data-action="close-study" aria-label="保存并退出学习">✕</button></div><div class="study-progress"><i style="width:${Math.min(100,session.completed/session.total*100)}%"></i></div><div class="flashcard"><span class="pill">${labels[item.kind]||labels.review}</span><div class="flash-word">${esc(w.word)}</div><div class="phonetic-line">${esc(w.phonetic?'/'+w.phonetic+'/':'')}<button class="icon-button" data-speak="${esc(w.id)}" aria-label="朗读单词">♪</button><button class="icon-button ${state.favoriteIds.includes(w.id)?'selected':''}" data-favorite="${esc(w.id)}" aria-label="收藏单词">${state.favoriteIds.includes(w.id)?'★':'☆'}</button></div>${session.revealed?`<div class="meaning">${esc(shortMeaning(w.meaning))}</div>${w.meaning!==shortMeaning(w.meaning)?`<details class="meaning-more"><summary>展开完整释义</summary><p style="white-space:pre-line;line-height:1.9;margin-top:12px">${esc(w.meaning)}</p></details>`:''}<p class="subtle">先掌握常见意思，再口头造句。第一遍不必背下所有义项。</p>`:'<p class="recall-hint">先在脑海里说出它的意思。<br>哪怕一时想不起来，也给自己几秒钟。</p>'}</div><div class="study-bottom">${session.revealed?'<div class="rating-row"><button class="rating again" data-grade="again">没想起来<small>隔几个词再试</small></button><button class="rating" data-grade="hard">有点模糊<small>缩短间隔</small></button><button class="rating good" data-grade="good">记住了<small>按计划复习</small></button></div>':'<button class="btn btn-primary wide" data-action="reveal">翻开答案 · 检查回忆</button>'}<p class="study-caption">诚实反馈，比刷完数量更重要。每次作答都会保存。</p></div>`;}
  function gradeCard(rating) {if(!session||session.type!=='cards'||!session.revealed)return;const item=session.queue.shift();try{persist(E.grade(state,item.id,rating,today()));}catch(err){toast(err.message);session.queue.unshift(item);return;}if(rating==='again'){session.queue.push({...item,kind:'retry'});}else{session.completed++;}session.revealed=false;renderStudy();render();}
  function shuffle(list) {const result=[...list];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
  function startFoundationCheck() { const ids=(window.WORD_META||{}).foundationCheckIds || []; const pool=ids.map(id=>byId.get(String(id))).filter(Boolean); const chosen=(pool.length?pool:words.filter(w=>w.base&&w.word.length>=5)).slice(0,20); if(!chosen.length){toast('基础词库尚未加载。');return;} session={type:'choice',queue:chosen.map(w=>({id:String(w.id)})),total:chosen.length,completed:0,correct:0,answered:false,wrong:[],date:today(),preview:true,foundation:true}; $('#study-dialog').showModal();renderStudy(); }
  function startQuiz(mode) {const learned=words.filter(w=>state.records[w.id]?.learned&&!state.knownIds.includes(w.id));const pool=learned.length?learned:core;const chosen=shuffle(pool).slice(0,10);if(!chosen.length){toast('还没有可用词条。');return;}session={type:mode,queue:chosen.map(w=>({id:String(w.id)})),total:chosen.length,completed:0,correct:0,answered:false,wrong:[],date:today(),preview:!learned.length};$('#study-dialog').showModal();renderStudy();}
  function renderQuiz(w) {const spelling=session.type==='spelling';if(!session.options)session.options=shuffle([w,...shuffle((session.foundation?words.filter(x=>x.base):core).filter(x=>x.id!==w.id&&x.meaning!==w.meaning)).slice(0,3)]);$('#study-content').innerHTML=`<div class="study-top"><span>${spelling?'拼写检索':'词义自测'} · ${session.completed+1} / ${session.total}${session.foundation?' · 基础补漏':session.preview?' · 预习模式':''}</span><button class="close-button" data-action="close-study" aria-label="退出自测">✕</button></div><div class="study-progress"><i style="width:${session.completed/session.total*100}%"></i></div><div class="flashcard"><span class="pill">先检索，再核对</span>${spelling?`<div class="meaning" style="margin-top:8px">${esc(shortMeaning(w.meaning))}</div><p class="subtle">${w.word.length} 个字符 · 回想英文拼写</p>`:`<div class="flash-word">${esc(w.word)}</div><p class="subtle">选择最恰当的释义</p>`}${session.answered?`<div class="feedback ${session.lastCorrect?'':'wrong'}">${session.lastCorrect?'✓ 回答正确':'这次没有答对，再读一遍正确答案。'}<br><strong>${esc(w.word)}</strong> — ${esc(w.meaning)}</div>`:spelling?'<form id="spelling-form" class="spelling-form"><input id="spelling-answer" aria-label="输入英文单词" placeholder="输入你记住的单词" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false"><button class="btn btn-primary" type="submit">核对答案</button></form>':`<div class="answer-options">${session.options.map(o=>`<button data-answer="${esc(o.id)}">${esc(o.meaning)}</button>`).join('')}</div>`}</div><div class="study-bottom">${session.answered?'<button class="btn btn-primary wide" data-action="next-question">下一题 →</button>':'<button class="btn btn-light wide" data-action="dont-know">暂时想不起来 · 看答案</button>'}<p class="study-caption">自测不增加已学数量。基础补漏答错词会加入计划；已学错词重新安排复习。</p></div>`;if(spelling&&!session.answered)$('#spelling-answer')?.focus();}
  function answerQuiz(answer) {if(!session||session.answered)return;const w=byId.get(session.queue[0].id);session.lastCorrect=session.type==='spelling'?answer.trim().toLowerCase().replace(/\s+/g,' ')===w.word.toLowerCase():answer===String(w.id);session.answered=true;if(session.lastCorrect)session.correct++;else{session.wrong.push(w.id);if(session.foundation){persist({...state,extraIds:state.extraIds.includes(w.id)?state.extraIds:[...state.extraIds,w.id],knownIds:state.knownIds.filter(id=>id!==w.id)});}if(state.records[w.id]?.learned){try{persist(E.grade(state,w.id,'again',today()));}catch(_){/* A completed daily review is not advanced by practice. */}}}renderStudy();}
  function nextQuestion(){if(!session)return;session.queue.shift();session.completed++;session.answered=false;session.options=null;renderStudy();}
  function renderFinish(){const isCards=session.type==='cards',s=stats();$('#study-content').innerHTML=`<div class="study-top"><span>一次小小的进步</span><button class="close-button" data-action="close-study" aria-label="关闭结果">✕</button></div><div class="flashcard finish"><div class="finish-icon">✳</div><h2>${isCards?'这一组，完成了。':'回忆越主动，记忆越扎实。'}</h2><p>${isCards?`你认真完成了 ${session.completed} 个词的回忆。<br>下一次重逢，已经安排好了。`:`本次答对 ${session.correct} / ${session.total} 题。<br>${session.wrong.length?(session.foundation?'不会的基础词已加入学习计划。':'错词已列在下方，建议隔一会儿再次检索。'):'做得好，明天再检验一次记忆。'}`}</p>${!isCards&&session.wrong.length?`<p>${session.wrong.map(id=>esc(byId.get(String(id))?.word||id)).join(' · ')}</p>`:''}</div><div class="study-bottom"><button class="btn btn-primary wide" data-action="finish-study">${E.canCheckIn(state,words,today())&&!s.checkedIn?'完成今日任务并打卡':'返回学习空间'}</button><p class="study-caption">${s.newRemaining||s.dueRemaining?`今日新词还差 ${s.newRemaining} 个；待复习/重试 ${s.dueRemaining} 个（可能包含未完成的新词）。`:'今天的词汇任务已经完成。记得给自己一点肯定。'}</p></div>`;render();}
  function closeStudy(){ $('#study-dialog').close();session=null;if('speechSynthesis'in window)speechSynthesis.cancel();render();}
  function checkIn(){try{if(!E.canCheckIn(state,words,today())){const s=stats();toast(`还需完成 ${s.newRemaining} 个新词和 ${s.dueRemaining} 个待复习词。`);return;}persist(E.checkIn(state,words,today()));toast('今日打卡完成。每一天都算数。');render();}catch(err){toast(err.message);}}
  function backup(){return JSON.stringify({app:'word42',version:1,exportedAt:new Date().toISOString(),state,preferences:prefs},null,2);}
  function restore(raw) {
    try {
      if (typeof raw !== 'string' || raw.length > 5*1024*1024) throw Error('备份须为5MB以内的JSON文本。');
      const input=JSON.parse(raw);
      if(input.app && (input.app!=='word42'||input.version!==1))throw Error('不是受支持的词序42备份。');
      const next=E.validateImport(input.state||input,words);
      let nextPrefs={readDays:[],readingNotes:{},showTranslation:true};
      if(input.preferences!==undefined){
        const p=input.preferences;
        if(!p||typeof p!=='object'||!Array.isArray(p.readDays)||p.readDays.some(n=>!Number.isInteger(n)||n<1||n>42)||typeof p.showTranslation!=='boolean'||!p.readingNotes||typeof p.readingNotes!=='object'||Array.isArray(p.readingNotes))throw Error('阅读记录格式无效。');
        nextPrefs.readDays=[...new Set(p.readDays)];nextPrefs.showTranslation=p.showTranslation;
        for(const [k,v]of Object.entries(p.readingNotes)){
          if(!/^([1-9]|[1-3][0-9]|4[0-2])$/.test(k)||typeof v!=='string'||v.length>20000)throw Error('笔记格式无效，或单篇笔记超过20000字符；当前数据未修改。');
          nextPrefs.readingNotes[k]=v;
        }
      }
      if(!confirm('已通过格式校验。恢复备份会覆盖当前设备的学习记录，是否继续？'))return;
      persist(next);prefs=nextPrefs;savePrefs();toast('备份已恢复。');render();
    } catch(error) {toast('恢复失败：'+error.message);}
  }
  async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}openDetail('<span class="eyebrow">TAKE YOUR WORDS WITH YOU</span><h1>在手机上使用词序42</h1><p>在 Mate 80 的浏览器中打开应用网址，然后查看浏览器菜单是否提供“添加到桌面”或“安装”。没有该选项时可以收藏网址。</p><p>第一次在线打开后，应用会尝试缓存词库与页面。离线可用性由浏览器支持和缓存是否保留决定。</p><p>原生鸿蒙安装需要配套工程经 DevEco Studio 编译和设备签名。网页入口与原生 HAP 是两种交付方式。</p><p>更换浏览器或设备前，请在“计划与设置”导出进度。</p>');}
  document.addEventListener('click',event=>{const b=event.target.closest('button,[data-nav]');if(!b)return;
    if(b.dataset.nav){go(b.dataset.nav);return;}
    if(b.dataset.start){openStudy(b.dataset.start);return;}
    if(b.dataset.quiz){startQuiz(b.dataset.quiz);return;}
    if(b.dataset.filter){libraryTab=b.dataset.filter;page=1;render();return;}
    if(b.dataset.page){page=Number(b.dataset.page);render();window.scrollTo({top:0,behavior:'instant'});return;}
    if(b.dataset.speak){speak(b.dataset.speak);return;}
    if(b.dataset.favorite){const id=byId.get(b.dataset.favorite)?.id;if(id===undefined)return;const ids=state.favoriteIds.includes(id)?state.favoriteIds.filter(x=>x!==id):[...state.favoriteIds,id];persist({...state,favoriteIds:ids});if($('#detail-dialog').open&&view==='library')showWord(String(id));if(session&&session.type==='cards')renderStudy();render();return;}
    if(b.dataset.known){const id=byId.get(b.dataset.known)?.id;if(id===undefined)return;persist({...state,knownIds:state.knownIds.includes(id)?state.knownIds.filter(x=>x!==id):[...state.knownIds,id]});toast(state.knownIds.includes(id)?'已标记熟悉，将跳过学习；再次点击可恢复。':'已重新加入学习。');render();return;}
    if(b.dataset.extra){const id=byId.get(b.dataset.extra)?.id;if(id!==undefined){persist({...state,extraIds:state.extraIds.includes(id)?state.extraIds:[...state.extraIds,id],knownIds:state.knownIds.filter(x=>x!==id)});toast(byId.get(String(id)).base?'已恢复基础补漏，将优先安排。':'已加入扩展计划；会排在未学冲刺词之后。');showWord(String(id));}return;}
    if(b.dataset.word){showWord(b.dataset.word);return;}
    if(b.dataset.article){showArticle(b.dataset.article);return;}
    if(b.dataset.essay){showEssay(Number(b.dataset.essay));return;}
    if(b.dataset.grade){gradeCard(b.dataset.grade);return;}
    if(b.dataset.answer){answerQuiz(b.dataset.answer);return;}
    if(b.dataset.read){const day=Number(b.dataset.read);const note=$('#essay-notes')?.value||'';if(note.length>20000){toast('单篇笔记最多20000字符，请缩短后保存。');return;}prefs.readingNotes[day]=note;if(!prefs.readDays.includes(day))prefs.readDays.push(day);savePrefs();toast('练习笔记已保存。');render();return;}
    const a=b.dataset.action;
    if(a==='foundation-check')startFoundationCheck();
    if(a==='reveal'){session.revealed=true;renderStudy();}
    if(a==='close-study')closeStudy();
    if(a==='finish-study'){if(E.canCheckIn(state,words,today())&&!stats().checkedIn)checkIn();closeStudy();}
    if(a==='next-question')nextQuestion();
    if(a==='dont-know')answerQuiz('');
    if(a==='checkin')checkIn();
    if(a==='save-date'){const date=$('#start-date').value;try{if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today()||date<'2000-01-01')throw Error('请选择不晚于今天的有效日期。');const next=E.validateImport({...state,startDate:date},words);persist(next);toast('计划日期已更新。');render();}catch(err){toast(err.message);}}
    if(a==='backup-text'){$('#backup-text').value=backup();$('#backup-text').focus();$('#backup-text').select();toast('备份文本已生成，可全选复制保存。');}
    if(a==='export'){if(window.WORD42_NATIVE){$('#backup-text').value=backup();$('#backup-text').focus();$('#backup-text').select();toast('鸿蒙本地版请复制备份文本保存。');return;}const blob=new Blob([backup()],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`词序42-进度-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份文件已生成。');}
    if(a==='import-text')restore($('#backup-text').value);
    if(a==='install')install();
    if(a==='reset'&&confirm('这会清空当前设备全部单词进度和写作笔记。建议先备份。确定重新开始？')){persist(E.createState(today()));prefs={readDays:[],readingNotes:{},showTranslation:true};savePrefs();render();toast('已开始新的42天计划。');}
  });
  document.addEventListener('input',event=>{if(event.target.id==='word-search'){search=event.target.value;page=1;const pos=event.target.selectionStart;render();const input=$('#word-search');input.focus();try{input.setSelectionRange(pos,pos);}catch(_){}}});
  document.addEventListener('change',event=>{if(event.target.id==='show-basic'){showBasic=event.target.checked;page=1;render();}if(event.target.id==='translation-toggle'){prefs.showTranslation=event.target.checked;savePrefs();document.querySelectorAll('.chinese').forEach(p=>p.hidden=!prefs.showTranslation);}if(event.target.id==='import-file'){const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('备份文件过大，请选择5MB以内的JSON文件。');return;}file.text().then(restore).catch(()=>toast('无法读取这个文件。'));}});
  document.addEventListener('submit',event=>{if(event.target.id==='spelling-form'){event.preventDefault();answerQuiz($('#spelling-answer').value);}});
  $('#detail-close').addEventListener('click',()=>$('#detail-dialog').close());
  $('#study-dialog').addEventListener('cancel',()=>{session=null;render();});
  window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==view){view=navs.some(n=>n[0]===next)||next==='settings'?next:'home';render();}});
  window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
  window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue){try{state=E.validateImport(JSON.parse(event.newValue),words);if(session){closeStudy();toast('另一页面已更新进度，请重新开始当前学习组。');}render();}catch(_){toast('另一页面的进度无法读取，请导出当前备份。');}}});
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(session&&session.date!==today()){closeStudy();toast('新的一天开始了，学习任务已更新。');}else if(!session)render();}});
  if(!window.WORD42_DISABLE_SW&&'serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
  view=location.hash.slice(1)||'home';if(!navs.some(n=>n[0]===view)&&view!=='settings')view='home';render();
})();


